    13→enum RoomScreenViewModelAction: Equatable {
    14→    case focusEvent(eventID: String)
    15→    case displayThread(threadRootEventID: String, focussedEventID: String)
    16→    case displayPinnedEventsTimeline
    17→    case displayRoomDetails
    18→    case displayCall
    19→    case removeComposerFocus
    20→    case displayKnockRequests
    21→    case displayRoom(roomID: String, via: [String])
    22→    case displayMessageForwarding(MessageForwardingItem)
    23→}
    24→
    25→enum RoomScreenViewAction {
    26→    case tappedPinnedEventsBanner
    27→    case viewAllPins
    28→    case displayRoomDetails
    29→    case displayCall
    30→    case footerViewAction(RoomScreenFooterViewAction)
    31→    case acceptKnock(eventID: String)
    32→    case dismissKnockRequests
    33→    case viewKnockRequests
    34→    case displaySuccessorRoom
    35→}
    36→
    37→struct RoomScreenViewState: BindableState {
    38→    var roomTitle = ""
    39→    var roomAvatar: RoomAvatar
    40→    var dmRecipientVerificationState: UserIdentityVerificationState?
    41→    
    42→    var lastScrollDirection: ScrollDirection?
    43→    // This is used to control the banner
    44→    var pinnedEventsBannerState: PinnedEventsBannerState = .loading(numbersOfEvents: 0)
    45→    var shouldShowPinnedEventsBanner: Bool {
    46→        !pinnedEventsBannerState.isEmpty && lastScrollDirection != .top
    47→    }
    48→    
    49→    var canSendMessage = true
    50→    
    51→    /// Whether or not starting a call is supported.
    52→    var isCallingEnabled = true
    53→    /// Whether or not the user is allowed to join calls in this room.
    54→    var canJoinCall = false
    55→    /// Whether or not this room currently has a call in progress.
    56→    var hasOngoingCall: Bool
    57→    /// Whether or not the user is already part of a call in another room.
    58→    var isParticipatingInOngoingCall = false
    59→    var shouldShowCallButton: Bool {
    60→        isCallingEnabled && !isParticipatingInOngoingCall // Hide the join call button when already in the call
    61→    }
    62→    
    63→    var isKnockingEnabled = false
    64→    var isKnockableRoom = false
    65→    var canAcceptKnocks = false
    66→    var canDeclineKnocks = false
    67→    var canBan = false
    68→    var unseenKnockRequests: [KnockRequestInfo] = []
    69→    var handledEventIDs: Set<String> = []
    70→    
    71→    var hasSuccessor: Bool
    72→    
    73→    var displayedKnockRequests: [KnockRequestInfo] {
    74→        unseenKnockRequests.filter { !handledEventIDs.contains($0.eventID) }
    75→    }
    76→    
    77→    var shouldSeeKnockRequests: Bool {
    78→        isKnockingEnabled &&
    79→            isKnockableRoom &&
    80→            !displayedKnockRequests.isEmpty &&
    81→            (canAcceptKnocks || canDeclineKnocks || canBan)
    82→    }
    83→    
    84→    /// If `enableKeyShareOnInvite` is set, determines the current history sharing state.
    85→    var roomHistorySharingState: RoomHistorySharingState?
    86→    
    87→    var footerDetails: RoomScreenFooterViewDetails?
    88→    
    89→    var bindings = RoomScreenViewStateBindings()
    90→}
    91→
    92→struct RoomScreenViewStateBindings {
    93→    /// The view model used to present a QuickLook media preview.
    94→    var mediaPreviewViewModel: TimelineMediaPreviewViewModel?
    95→    var alertInfo: AlertInfo<RoomScreenAlertType>?
    96→}
